#include <stdio.h>

int main() {
    char text[] = "banana";
    int frequency[26] = {0};

    for (int i = 0; text[i] != '\0'; i++) {
        frequency[text[i] - 'a']++;
    }

    for (int i = 0; i < 26; i++) {
        if (frequency[i] > 0) {
            printf("'%c': %d\n", 'a' + i, frequency[i]);
        }
    }

    return 0;
}
